-- Create these disposable accounts in the staging Auth dashboard first.
-- No password is stored or generated by this script.
begin;
do $$
declare
  admin_id uuid;
  member_id uuid;
  subject_id uuid;
  label text;
  agent_id uuid;
  settings jsonb := __SYNTHETIC_SETTINGS__;
  profile jsonb := __SYNTHETIC_PROFILE__;
begin
  if not exists(select 1 from pg_proc
    where oid='neo_private.push_dispatch_wake()'::regprocedure
      and position('https://qnuluspqfazdppciermw.supabase.co/functions/v1/push-dispatch' in pg_get_functiondef(oid))>0)
    or position('https://qnuluspqfazdppciermw.supabase.co/functions/v1/push-dispatch'
      in pg_get_functiondef('neo_private.support_push_wake()'::regprocedure))=0 then
    raise exception 'Os dois triggers precisam usar o destino de homologação.';
  end if;
  if exists(select 1 from auth.users
    where email is null or email not in ('admin-ma@example.invalid','participante-ma@example.invalid')) then
    raise exception 'Foram encontradas contas fora da fixture de homologação.';
  end if;
  select id into strict admin_id from auth.users where email='admin-ma@example.invalid';
  select id into strict member_id from auth.users where email='participante-ma@example.invalid';

  insert into neo_private.admin_members(user_id) values(admin_id) on conflict do nothing;
  foreach subject_id in array array[admin_id,member_id] loop
    perform set_config('request.jwt.claim.sub',subject_id::text,true);
    label := case when subject_id=admin_id then 'Equipe fictícia' else 'Participante fictício' end;
    if not exists(select 1 from public.neo_profiles where user_id=subject_id) then
      perform public.neo_complete_onboarding(profile||jsonb_build_object('name',label),settings,true,true);
    end if;
  end loop;

  perform set_config('request.jwt.claim.sub',admin_id::text,true);
  foreach label in array array['MA Staging A','MA Staging B'] loop
    if not exists(select 1 from neo_private.agents where admin_name=label) then
      agent_id := (public.neo_multiagent('create',jsonb_build_object('public_name',label,'admin_name',label))->'agent'->>'id')::uuid;
      perform public.neo_multiagent('save',jsonb_build_object('agent_id',agent_id,'expected_revision',1,
        'settings',jsonb_build_object('status','inactive','mode','suggest','daily_limit',3,
          'description','Fixture de homologação','purpose','Verificar isolamento',
          'instructions','Responda com o contexto sintético deste agente.')));
      perform public.neo_multiagent('knowledge_save',jsonb_build_object('agent_id',agent_id,
        'category','faq','title','Referência '||label,'content','Texto sintético exclusivo de '||label));
    end if;
  end loop;
  if not exists(select 1 from neo_private.agent_catalog_knowledge k where k.agent_id is null and k.title='Referência compartilhada MA') then
    select id into strict agent_id from neo_private.agents where admin_name='MA Staging A';
    perform public.neo_multiagent('knowledge_save',jsonb_build_object('agent_id',agent_id,'shared',true,
      'category','faq','title','Referência compartilhada MA','content','Texto sintético para ambos os agentes.'));
  end if;
end;
$$;
commit;
